// ─────────────────────────────────────────────────────────────
//  hooks/useFoods.js
//  Reusable hook that manages fetch state for food data
// ─────────────────────────────────────────────────────────────

import { useState, useEffect, useCallback } from 'react';
import { getRecommendations, searchByQuery } from '../services/openFoodFacts';

// ── Hook: personalised recommendations ──────────────────────
export function useRecommendations(preferences, count = 20) {
  const [foods,   setFoods]   = useState([]);
  const [loading, setLoading] = useState(true);
  const [error,   setError]   = useState(null);

  const load = useCallback(async () => {
    if (!preferences?.dietType) return;
    setLoading(true);
    setError(null);
    try {
      const results = await getRecommendations(preferences, count);
      setFoods(results);
    } catch (e) {
      setError('Failed to load recommendations. Please try again.');
    } finally {
      setLoading(false);
    }
  }, [preferences, count]);

  useEffect(() => { load(); }, [load]);

  return { foods, loading, error, reload: load };
}

// ── Hook: search query ───────────────────────────────────────
export function useSearch(query, preferences) {
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState(null);

  useEffect(() => {
    if (!query || query.trim().length < 2) {
      setResults([]);
      return;
    }

    let cancelled = false;
    setLoading(true);
    setError(null);

    const timer = setTimeout(async () => {
      try {
        const data = await searchByQuery(query, preferences || {}, 25);
        if (!cancelled) setResults(data);
      } catch {
        if (!cancelled) setError('Search failed. Please try again.');
      } finally {
        if (!cancelled) setLoading(false);
      }
    }, 500); // 500ms debounce

    return () => { cancelled = true; clearTimeout(timer); };
  }, [query, preferences]);

  return { results, loading, error };
}
